SELECT risk_user.user_id, risk_user.username, risk_user.real_name, risk_user.phone, risk_user.risk_level, risk_user.risk_score, risk_user.last_measure_time, risk_user.inactive_days, risk_user.recent_record_count, risk_user.abnormal_count, risk_user.highest_blood_sugar, risk_user.risk_reasons FROM (
) risk_user WHERE risk_user.risk_score > 0
AND risk_user.risk_level = #{query.riskLevel}
AND ( risk_user.username LIKE CONCAT('%', #{query.keyword}, '%') OR risk_user.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR risk_user.phone LIKE CONCAT('%', #{query.keyword}, '%') )
ORDER BY risk_user.risk_level , risk_user.risk_score DESC, risk_user.inactive_days DESC, risk_user.user_id DESC
